import attr, functools
@attr.s(slots=True)
class A:
    x = attr.ib()
    @property
    def p(self):
        raise AttributeError('I am a property')
    @functools.cached_property
    def f(self):
        return self.p
    @functools.cached_property
    def g(self):
        return self.x * 2
a = A(1)
for name in ('p','f'):
    try:
        getattr(a, name)
    except AttributeError as e:
        print(name, '->', e)
print('g ->', a.g)
try:
    a.z
except AttributeError as e:
    print('z ->', e)
"

